mapper.select:
/* AbnormalMapper.selectAbnormalList : 배송지변경신고 List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.OD_JOB_NO ,odAdnor.AR_DATE ,odAdnor.MRN ,odAdnor.MSN ,od.MBL_NO ,od.BOUND ,od.BOUND_TYPE ,COUNT(1) OVER (PARTITION BY od.OD_JOB_NO) AS HBL_CNT ,od.SHIPPER_ATTN ,od.HBL_NO ,od.MASTER_OD_JOB_NO ,od.HSN
,CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 0 ELSE od.PIECES END AS HBL_PIECES ,CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 0 ELSE od.GWT END AS HBL_GWT ,odAdnor.PIECES ,odAdnor.GWT ,odAdnor.CNT ,odAdnor.ABNORMAL_CODE ,(SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = odAdnor.ABNORMAL_CODE AND GROUP_CODE = 'ABNORMALITY_CODE') AS ABNORMAL_CODE_NAME ,odAdnor.DISC_WH_CODE ,CASE WHEN odAdnor.SEND_DATE IS NULL THEN 'N' ELSE 'Y' END AS SEND_YN ,odAdnor.SEQ_NO_ID ,odAdnor.REGISTER_DATE_TIME ,od.VENDER_ID_1 as VENDER_ID1 FROM TB_ECM_OD od INNER JOIN TB_ECM_OD mod ON od.MASTER_OD_JOB_NO = mod.OD_JOB_NO LEFT OUTER JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO INNER JOIN TB_ECM_OD_ABNORMAL odAdnor ON od.OD_JOB_NO = odAdnor.OD_JOB_NO WHERE od.ENT_CODE = #{srchEntCode} AND ISNULL(odAdnor.SEND_DATE,'') = ''
AND od.BOUND = 'SEA'
AND od.BOUND = 'AIR'
AND odAdnor.ABNORMAL_CODE = #{srchAbnormalCode}
AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND od.OD_JOB_NO IN (
#{item.odJobNo}
)

/* AbnormalMapper.selectBmsInPlanAbnormalList : 배송지변경신고 List(반입예정데이터) */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT bip.IN_PLAN_NO AS OD_JOB_NO ,odAdnor.AR_DATE ,odAdnor.MRN ,odAdnor.MSN ,bip.MBL_NO ,'AIR' AS BOUND ,'IMP' AS BOUND_TYPE ,COUNT(1) OVER (PARTITION BY bip.IN_PLAN_NO) AS HBL_CNT ,bip.BL_NO AS HBL_NO ,SUBSTRING(bip.CARGO_REFERENCE_NO, 16, 4) AS HSN ,CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 0 ELSE bip.EX_CT END AS HBL_PIECES ,CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 0 ELSE bip.EX_WT END AS HBL_GWT ,odAdnor.PIECES ,odAdnor.GWT ,odAdnor.CNT ,odAdnor.ABNORMAL_CODE ,(SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND CODE = odAdnor.ABNORMAL_CODE AND GROUP_CODE = 'ABNORMALITY_CODE') AS ABNORMAL_CODE_NAME ,odAdnor.DISC_WH_CODE ,CASE WHEN odAdnor.SEND_DATE IS NULL THEN 'N' ELSE 'Y' END AS SEND_YN ,odAdnor.SEQ_NO_ID ,odAdnor.REGISTER_DATE_TIME ,'QQ' AS VENDER_ID1 FROM TB_BMS_IN_PLAN bip WITH (NOLOCK) INNER JOIN TB_ECM_OD_ABNORMAL odAdnor ON odAdnor.OD_JOB_NO = CONVERT(VARCHAR(20), bip.IN_PLAN_NO) WHERE ISNULL(odAdnor.SEND_DATE,'') = ''
AND odAdnor.ABNORMAL_CODE = #{srchAbnormalCode}
AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND bip.IN_PLAN_NO IN (
#{item.odJobNo}
)

/* AbnormalMapper.selectAbnormalDeclareList : 배송지변경신고 List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
WITH Main_CTE AS( SELECT A.* FROM ( SELECT X.* ,(SELECT CONCAT('H.B/L ',NAME_${userLanguage}) FROM exps_master.dbo.TB_SMS_MESSAGE WHERE MESSAGE_ID = CASE MOD_TYPE WHEN '05' THEN 'EXPS003300' WHEN '06' THEN 'EXPS001554' WHEN '07' THEN 'EXPS001463' END) AS MOD_TYPE_NAME FROM( SELECT od.OD_JOB_NO ,odAdnor.SEQ_NO_ID ,odAdnor.AR_DATE ,odAdnor.MRN ,odAdnor.MSN ,od.MBL_NO ,od.HBL_NO ,od.PO_DATE ,od.MASTER_OD_JOB_NO ,od.HSN ,od.DEST_CODE ,od.DEST_PORT ,od.VESSEL_FLIGHT
,CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 0 ELSE od.PIECES END AS HBL_PIECES ,CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 0 ELSE od.GWT END AS HBL_GWT ,SUM(CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 1 ELSE 0 END ) OVER (PARTITION BY od.OD_JOB_NO) AS MFN_CNT ,odAdnor.PIECES ,odAdnor.GWT ,odAdnor.CNT ,odAdnor.ABNORMAL_CODE ,CONCAT(odAdnor.ABNORMAL_CODE, '.', (SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = odAdnor.ABNORMAL_CODE AND GROUP_CODE = 'ABNORMALITY_CODE')) AS ABNORMAL_CODE_NAME ,odAdnor.DISC_WH_CODE ,odAdnor.SEND_DATE ,odAdd.CARRYIN_DATE ,odAdd.UNMANAGEMENT_DATE ,odAdd.MF_CORRECTION_DATE ,odAdd.MF_CORRECTION_CONTENTS ,odAdd.ABNORMAL_MFN_DATE ,odAdd.ABNORMAL_MFN_YN ,od.MRN AS MOD_MRN ,od.SHIPPER_NAME ,od.SHIPPER_TEL ,od.CONSIGNEE_NAME ,od.PIECES AS MOD_PIECES ,od.GWT AS MOD_GWT ,od.COMMODITY_ITEM ,od.BOUND
,(SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = odAdd.LAST_POD_STATUS) AS LAST_POD_STATUS
,odAdd.LAST_POD_STATUS
,(SELECT TOP 1 MOD_TYPE FROM TB_EDI_MOD_HBL WHERE OD_JOB_NO = od.OD_JOB_NO ORDER BY REGISTER_DATE_TIME DESC) AS MOD_TYPE
,od.VENDER_ID_1 as VENDER_ID1 ,(SELECT SEND_DATE FROM TB_ECM_OD_ABNORMAL WHERE OD_JOB_NO = od.OD_JOB_NO AND SEQ_NO_ID = 2) AS MGN_MFN_SEND_DATE
,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) AS CONSIGNEE_TEL
,od.CONSIGNEE_TEL
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD mod ON od.MASTER_OD_JOB_NO = mod.OD_JOB_NO LEFT OUTER JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO INNER JOIN TB_ECM_OD_ABNORMAL odAdnor ON od.OD_JOB_NO = odAdnor.OD_JOB_NO AND odAdnor.SEQ_NO_ID = 1 WHERE od.ENT_CODE = #{srchEntCode}
AND od.BOUND = 'SEA'
AND ISNULL(odAdnor.SEND_DATE,'') <> '' AND od.BOUND = 'AIR'
AND ${srchNoType} IN (#{item})
AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND CONVERT(DATE, ${srchDateGbn}, ${srchDateFormat}) <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND odAdnor.ABNORMAL_CODE = #{srchAbnormalCode}
AND ISNULL(odAdd.UNMANAGEMENT_DATE,'') <> ''
AND ISNULL(odAdd.UNMANAGEMENT_DATE,'') = ''
AND ISNULL(odAdd.MF_CORRECTION_DATE,'') <> ''
AND ISNULL(odAdd.MF_CORRECTION_DATE,'') = ''
AND odAdd.ABNORMAL_MFN_YN = 'Y'
AND (odAdd.ABNORMAL_MFN_YN = 'N' OR odAdd.ABNORMAL_MFN_YN IS NULL)
AND odAdd.CARRYIN_DATE IS NOT NULL AND odAdd.CARRYIN_DATE <> ''
AND (odAdd.CARRYIN_DATE IS NULL OR odAdd.CARRYIN_DATE = '')
AND od.OD_JOB_NO IN (
#{item.odJobNo}
)
AND od.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}
) X ) A
) , Count_CTE AS ( SELECT COUNT(*) AS TOTAL FROM Main_CTE ) SELECT *
, ROW_NUMBER() OVER(
, ${defaultSort2}
) AS NUM FROM Count_CTE, Main_CTE
, ${defaultSort2}
OFFSET ${startNum} ROWS FETCH NEXT ${pageSize} ROWS ONLY

/* AbnormalMapper.selectBmsInPlanAbnormalDeclareList : 배송지변경신고 List(반입예정데이터) */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; WITH Main_CTE AS( SELECT A.* FROM ( SELECT X.* FROM( SELECT bip.IN_PLAN_NO AS OD_JOB_NO ,odAdnor.SEQ_NO_ID ,odAdnor.AR_DATE ,odAdnor.MRN ,odAdnor.MSN ,bip.MBL_NO ,bip.BL_NO AS HBL_NO ,SUBSTRING(bip.CARGO_REFERENCE_NO, 16, 4) AS HSN ,bip.VESSEL_FLIGHT ,CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 0 ELSE bip.EX_CT END AS HBL_PIECES ,CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 0 ELSE bip.EX_WT END AS HBL_GWT ,SUM(CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 1 ELSE 0 END ) OVER (PARTITION BY bip.IN_PLAN_NO) AS MFN_CNT ,odAdnor.PIECES ,odAdnor.GWT ,odAdnor.CNT ,odAdnor.ABNORMAL_CODE ,CONCAT(odAdnor.ABNORMAL_CODE, '.', (SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND CODE = odAdnor.ABNORMAL_CODE AND GROUP_CODE = 'ABNORMALITY_CODE')) AS ABNORMAL_CODE_NAME ,odAdnor.DISC_WH_CODE ,odAdnor.SEND_DATE ,SUBSTRING(bip.CARGO_REFERENCE_NO, 1, 11) AS MOD_MRN ,bip.SHIPPER_NAME ,bip.SHIPPER_TEL ,bip.CONSIGNEE_NAME ,bip.EX_CT AS MOD_PIECES ,bip.EX_WT AS MOD_GWT ,bip.COMMODITY_ITEM_LOC ,'AIR' AS BOUND ,'QQ' AS VENDER_ID1 ,(SELECT SEND_DATE FROM TB_ECM_OD_ABNORMAL WHERE OD_JOB_NO = CONVERT(VARCHAR(20), bip.IN_PLAN_NO) AND SEQ_NO_ID = 2) AS MGN_MFN_SEND_DATE ,dbo.Cryptography(bip.OD_JOB_NO, bip.CONSIGNEE_TEL, 1) AS CONSIGNEE_TEL FROM TB_BMS_IN_PLAN bip WITH (NOLOCK) INNER JOIN TB_ECM_OD_ABNORMAL odAdnor ON odAdnor.OD_JOB_NO = CONVERT(VARCHAR(20), bip.IN_PLAN_NO) AND odAdnor.SEQ_NO_ID = 1 WHERE ISNULL(odAdnor.SEND_DATE,'') <> ''
AND ${srchNoType} IN (#{item})
AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND CONVERT(DATE, ${srchDateGbn}, ${srchDateFormat}) <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND odAdnor.ABNORMAL_CODE = #{srchAbnormalCode}
) X ) A
) , Count_CTE AS ( SELECT COUNT(*) AS TOTAL FROM Main_CTE ) SELECT *
, ROW_NUMBER() OVER(
, ${defaultSort2}
) AS NUM FROM Count_CTE, Main_CTE
, ${defaultSort2}
OFFSET ${startNum} ROWS FETCH NEXT ${pageSize} ROWS ONLY

/* AbnormalMapper.selectAbnormalAddPopupList : 하기이상추가팝업 List(반입예정데이터) */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT SUBSTRING(bip.CARGO_REFERENCE_NO, 1, 11) AS MRN ,SUBSTRING(bip.CARGO_REFERENCE_NO, 12, 4) AS MSN ,bip.MBL_NO ,bip.VESSEL_FLIGHT ,'AIR' AS BOUND ,bip.BL_NO AS HBL_NO ,SUBSTRING(bip.CARGO_REFERENCE_NO, 16, 4) AS HSN ,bip.EX_CT AS OD_PIECES ,bip.EX_WT AS GWT ,bip.AMOUNT_USD AS AMOUNT_CUR ,bip.CONSIGNEE_NAME ,CONCAT(bip.CONSIGNEE_ADDRESS_1, bip.CONSIGNEE_ADDRESS_2) AS CONSIGNEE_ADDRESS ,bip.AR_DATE ,bip.REGISTER_DATE_TIME AS PO_DATE FROM TB_BMS_IN_PLAN bip WITH (NOLOCK) WHERE bip.MBL_NO = #{srchMblNo}
AND bip.BL_NO = #{srchNo}

mapper.delete:
/* AbnormalMapper.deleteAbnormalList : 하기이상결과보고  delete */
	DELETE FROM TB_ECM_OD_ABNORMAL
	WHERE ISNULL(SEND_DATE,'') = ''
	AND (
	
	(OD_JOB_NO = #{item.odJobNo} AND SEQ_NO_ID = #{item.seqNoId})
	
	)

/* AbnormalMapper.deleteAbnormalList : 하기이상결과보고  delete */
	DELETE FROM TB_ECM_OD_SPECIAL_ITEM
	WHERE OD_JOB_NO IN(#{item.OD_JOB_NO})

mapper.update:
/* AbnormalMapper.updateAbnormal : 하기이상결과보고 update */
	UPDATE TB_ECM_OD_ABNORMAL SET
		   PIECES = #{PIECES}
		  ,GWT = #{GWT}
		  ,ABNORMAL_CODE = #{ABNORMAL_CODE}
		  ,CNT = #{CNT}
		  ,DISC_WH_CODE = #{DISC_WH_CODE}
		  ,AR_DATE = #{AR_DATE}
		  ,VESSEL_FLIGHT = #{VESSEL_FLIGHT}
		  ,UPDATE_USER_ID = #{registerUserId}
		  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	WHERE OD_JOB_NO = #{OD_JOB_NO}
	AND SEQ_NO_ID = #{SEQ_NO_ID}

/* AbnormalMapper.updateAbnormalAdditional : 하기이상결과보고신고 삭제건 ad update */
	UPDATE ad
	SET   ad.ABNORMAL_MFN_DATE = NULL
		, ad.ABNORMAL_MFN_YN = NULL
	
	 
		, ad.ABNORMAL_DATE = NULL
	
	
		, ad.ABNORMAL_DATE = #{sendDate}
	
	
	FROM TB_ECM_OD_ADDITIONAL ad
	INNER JOIN TB_ECM_OD_ABNORMAL abnormal
 		ON abnormal.OD_JOB_NO = ad.OD_JOB_NO
 	WHERE abnormal.OD_JOB_NO = #{odJobNo} AND abnormal.SEQ_NO_ID = #{seqNoId}

