/* AbnormalMapper.selectHblValidate : hbl유효성체크 */
WITH TMP AS( SELECT A.ENT_CODE, A.HBL_NO FROM (
SELECT #{entCode} AS ENT_CODE,#{item.HBL_NO} AS HBL_NO
) A LEFT JOIN TB_ECM_OD OD ON OD.ENT_CODE = #{entCode} AND A.HBL_NO = OD.HBL_NO WHERE OD.OD_JOB_NO IS NULL ) SELECT COUNT(TMP.HBL_NO) AS NOT_BL_CNT , STUFF((SELECT ',' + HBL_NO FROM TMP WHERE ENT_CODE = t.ENT_CODE FOR XML PATH('')), 1, 1, '') FROM TMP t GROUP BY t.ENT_CODE

