/* AbnormalMapper.insertExcelAbnormal : 하기이상결과보고 Excel insert */
INSERT INTO TB_ECM_OD_ABNORMAL
(
	OD_JOB_NO
	, SEQ_NO_ID
	, ABNORMAL_CODE
	, MRN
	, MSN
	, VESSEL_FLIGHT
	, DISC_WH_CODE
	, AR_DATE
	, PIECES
	, GWT
	, CNT
	, REGISTER_USER_ID
	, REGISTER_DATE_TIME
	, UPDATE_USER_ID
	, UPDATE_DATE_TIME)			
SELECT
	od.OD_JOB_NO
	,(SELECT ISNULL(MAX(SEQ_NO_ID),0) + 1 FROM TB_ECM_OD_ABNORMAL WHERE OD_JOB_NO = od.OD_JOB_NO )
	, #{ABNORMAL_CODE}
	, #{MRN}
	, #{MSN}
	, #{VESSEL_FLIGHT}
	, #{DISC_WH_CODE}
	, #{AR_DATE}
	, #{PIECES}
	, #{GWT}
	, #{CNT}
	,#{registerUserId}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())
	,#{registerUserId}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())		
FROM TB_ECM_OD od			
WHERE MBL_NO = LTRIM(RTRIM(REPLACE(#{MBL_NO},char(9),'')))
AND HBL_NO = LTRIM(RTRIM(REPLACE(#{HBL_NO},char(9),'')));

