mapper.select:
/* abnormalMapper.getNoRegisterCount : 하기이상 체크할 하우스 리스트 조회 */ SELECT COUNT(A.MGN) AS MGN_CNT ,COUNT(A.OTHER) AS OTHER_CNT ,COUNT(A.MGN_MFN) AS MGN_MFN_CNT ,COUNT(A.OD_JOB_NO) AS TOTAL_CNT FROM ( SELECT od.OD_JOB_NO ,MAX(CASE WHEN ab.ABNORMAL_CODE IN('MGN', 'SHT') THEN 1 END) AS MGN ,MAX(CASE WHEN ab.ABNORMAL_CODE NOT IN('MGN', 'SHT') THEN 1 END) AS OTHER ,CASE WHEN MAX(ab.ABNORMAL_CODE) IN('MGN', 'SHT') AND MIN(ab.ABNORMAL_CODE) = 'MFN' THEN 1 END AS MGN_MFN FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON od.OD_JOB_NO = ad.OD_JOB_NO LEFT JOIN TB_ECM_OD_ABNORMAL ab ON od.OD_JOB_NO = ab.OD_JOB_NO WHERE 1=1
AND od.OD_JOB_NO IN (
#{item}
)
AND od.MASTER_OD_JOB_NO = #{masterOdJobNo}
AND od.BL_TYPE_MH = 'H'
GROUP BY od.OD_JOB_NO ) A

